<?php
$allowedRoles=['super_admin','admin','manager','Admin','ro-super-admin','ro-admin','ro-manager'];
require_once '../../config/db_connection.php'; require_once '../../config/require_auth.php'; require_once 'purchase_order_helpers.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['status'=>'error','message'=>'Only POST requests are allowed.']);exit;}
$p=json_decode(file_get_contents('php://input'),true)?:[];$refundId=cleanId($p['refund_id']??null);$amount=round((float)($p['amount_received']??0),2);$date=trim((string)($p['received_date']??''));$reference=trim((string)($p['reference_number']??''));
if($refundId===''||$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){http_response_code(422);echo json_encode(['status'=>'error','message'=>'Refund, positive received amount, and received date are required.']);exit;}
try{ensurePurchaseOrderSchema($pdo);$pdo->beginTransaction();$s=$pdo->prepare('SELECT amount_due,amount_received FROM supplier_refunds WHERE refund_id=:id FOR UPDATE');$s->execute([':id'=>$refundId]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)throw new InvalidArgumentException('Supplier refund was not found.');$next=round((float)$r['amount_received']+$amount,2);if($next>(float)$r['amount_due'])throw new InvalidArgumentException('Refund received exceeds the amount due.');$status=$next>=(float)$r['amount_due']?'Received':'Partially Received';$pdo->prepare('UPDATE supplier_refunds SET amount_received=:amount,refund_status=:status,received_date=:date,reference_number=:reference,recorded_by=:user WHERE refund_id=:id')->execute([':amount'=>$next,':status'=>$status,':date'=>$date,':reference'=>$reference!==''?$reference:null,':user'=>$_SESSION['user_id']??null,':id'=>$refundId]);if($status==='Received')$pdo->prepare('UPDATE supplier_claims sc INNER JOIN supplier_refunds sr ON sr.claim_id=sc.claim_id SET sc.resolved_at=CURRENT_TIMESTAMP,sc.claim_status=\'Refund Received\' WHERE sr.refund_id=:id')->execute([':id'=>$refundId]);$pdo->commit();echo json_encode(['status'=>'success','message'=>'Supplier refund recorded.','refund_status'=>$status,'amount_received'=>$next,'balance'=>round((float)$r['amount_due']-$next,2)]);}catch(InvalidArgumentException $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(422);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['status'=>'error','message'=>'Unable to record supplier refund.']);}
?>
